interface UserRepository { Optional<String> findName(long id); }

// Same interface as the real repository; wraps it and adds caching
final class CachingUserRepository implements UserRepository {
    private final UserRepository inner;
    private final Map<Long, Optional<String>> cache = new ConcurrentHashMap<>();

    CachingUserRepository(UserRepository inner) { this.inner = inner; }

    @Override
    public Optional<String> findName(long id) {
        return cache.computeIfAbsent(id, inner::findName);   // delegate on a cache miss
    }
}

function createEmitter() {
  const listeners = new Set();
  return {
    subscribe(fn) {
      listeners.add(fn);
      return () => listeners.delete(fn);   // always keep and call this
    },
    emit(value) {
      for (const fn of [...listeners]) {     // snapshot: safe if a listener unsubscribes
        try { fn(value); } catch (e) { console.error(e); }   // one bad listener can't stop the rest
      }
    },
  };
}

