import java.util.List;

// S: Single Responsibility. Calculating, printing and saving live in separate classes.
record Invoice(String id, List<Long> items) {
    long total() { return items.stream().mapToLong(Long::longValue).sum(); }
}
class InvoicePrinter {
    String print(Invoice inv) { return inv.id() + " total=" + inv.total(); }
}

// O: Open/Closed. A new discount is a new class, not another branch in an if/else chain.
interface DiscountPolicy { long apply(long amount); }
class NoDiscount implements DiscountPolicy { public long apply(long a) { return a; } }
class EidDiscount implements DiscountPolicy { public long apply(long a) { return a * 90 / 100; } }

// L: Liskov Substitution. Square does NOT extend a mutable Rectangle; both are Shapes.
interface Shape { long area(); }
record Rect(long w, long h) implements Shape { public long area() { return w * h; } }
record Square(long side) implements Shape { public long area() { return side * side; } }

// I: Interface Segregation. Small role interfaces instead of one fat "Machine".
interface Printer { String print(String doc); }
interface DocScanner { String scan(); }
class BasicPrinter implements Printer {
    public String print(String doc) { return "printed " + doc; }
}
class OfficeMachine implements Printer, DocScanner {
    public String print(String doc) { return "printed " + doc; }
    public String scan() { return "scanned page"; }
}

// D: Dependency Inversion. The high-level service depends on abstractions that are injected.
interface InvoiceRepository { void save(Invoice inv); }
class InMemoryInvoiceRepository implements InvoiceRepository {
    public void save(Invoice inv) { System.out.println("saved " + inv.id()); }
}
class BillingService {
    private final InvoiceRepository repo;
    private final DiscountPolicy discount;

    BillingService(InvoiceRepository repo, DiscountPolicy discount) {
        this.repo = repo;
        this.discount = discount;
    }

    long bill(Invoice inv) {
        repo.save(inv);
        return discount.apply(inv.total());
    }
}

public class Main {
    public static void main(String[] args) {
        Invoice inv = new Invoice("INV-1", List.of(400L, 600L));
        System.out.println(new InvoicePrinter().print(inv));                 // INV-1 total=1000
        BillingService billing = new BillingService(new InMemoryInvoiceRepository(), new EidDiscount());
        System.out.println(billing.bill(inv));                               // saved INV-1, then 900
        for (Shape s : List.of(new Rect(5, 4), new Square(4))) System.out.println(s.area());  // 20, 16
        Printer printer = new BasicPrinter();                                // needs only printing
        System.out.println(printer.print("cv.pdf"));                         // printed cv.pdf
    }
}

