import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicLong;

// 1) Initialization-on-demand holder: lazy, thread-safe, no locking on reads
final class AppConfig {
    private AppConfig() { }                           // nobody else can call new

    private static class Holder {                     // loaded on the first getInstance() call
        static final AppConfig INSTANCE = new AppConfig();   // JVM class init is thread-safe
    }

    static AppConfig getInstance() { return Holder.INSTANCE; }
}

// 2) Enum singleton: thread-safe, serialization-safe and reflection-proof
enum IdGenerator {
    INSTANCE;
    private final AtomicLong next = new AtomicLong(1);
    long nextId() { return next.getAndIncrement(); }
}

// 3) Double-checked locking: correct ONLY because the field is volatile
final class Metrics {
    private static volatile Metrics instance;
    private Metrics() { }

    static Metrics getInstance() {
        Metrics local = instance;                     // one volatile read on the fast path
        if (local == null) {
            synchronized (Metrics.class) {
                local = instance;
                if (local == null) instance = local = new Metrics();
            }
        }
        return local;
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(8);
        Set<Object> seen = ConcurrentHashMap.newKeySet();
        List<Future<?>> tasks = new ArrayList<>();
        for (int i = 0; i < 100; i++) {
            tasks.add(pool.submit(() -> {
                seen.add(AppConfig.getInstance());
                seen.add(Metrics.getInstance());
                IdGenerator.INSTANCE.nextId();
            }));
        }
        for (Future<?> t : tasks) t.get();
        pool.shutdown();
        System.out.println("distinct instances: " + seen.size());          // 2 (one AppConfig + one Metrics)
        System.out.println("next id: " + IdGenerator.INSTANCE.nextId());   // 101
    }
}

