final class NotificationFactory {
    private static final Map<String, Supplier<Notification>> REGISTRY = Map.of(
        "email", EmailNotification::new,
        "sms", SmsNotification::new,
        "push", PushNotification::new
    );

    static Notification create(String channel) {
        Supplier<Notification> maker = REGISTRY.get(channel.toLowerCase());
        if (maker == null) throw new IllegalArgumentException("Unknown channel: " + channel);
        return maker.get();
    }
