import java.util.ArrayList;
import java.util.List;

public final class HttpRequest {
    private final String method, url;          // required
    private final List<String> headers;        // optional
    private final int timeoutMs;               // optional, has a default
    private final String body;                 // optional

    private HttpRequest(Builder b) {           // only the Builder can construct
        this.method = b.method;
        this.url = b.url;
        this.headers = List.copyOf(b.headers); // immutable copy
        this.timeoutMs = b.timeoutMs;
        this.body = b.body;
    }

    public static Builder builder(String method, String url) { return new Builder(method, url); }

    @Override public String toString() {
        return method + " " + url + " headers=" + headers + " timeout=" + timeoutMs + " body=" + body;
    }

    public static final class Builder {
        private final String method, url;
        private final List<String> headers = new ArrayList<>();
        private int timeoutMs = 5_000;
        private String body;

        private Builder(String method, String url) { this.method = method; this.url = url; }

        public Builder header(String name, String value) { headers.add(name + ": " + value); return this; }
        public Builder timeoutMs(int ms) { this.timeoutMs = ms; return this; }
        public Builder body(String body) { this.body = body; return this; }

        public HttpRequest build() {           // validate the WHOLE object once
            if (body != null && method.equals("GET")) throw new IllegalStateException("GET cannot have a body");
            if (timeoutMs <= 0) throw new IllegalStateException("timeout must be positive");
            return new HttpRequest(this);
        }
    }
}

class Main {
    public static void main(String[] args) {
        HttpRequest req = HttpRequest.builder("POST", "/api/orders")
                .header("Content-Type", "application/json")
                .timeoutMs(2_000)
                .body("{\"item\":\"rice\",\"qty\":2}")
                .build();
        System.out.println(req);
        try {
            HttpRequest.builder("GET", "/api/orders").body("oops").build();
        } catch (IllegalStateException e) {
            System.out.println("Rejected: " + e.getMessage());
        }
    }
}

// In TypeScript/JavaScript an options object with defaults often replaces a Builder
interface RequestOptions {
  headers?: Record<string, string>;
  timeoutMs?: number;
  body?: string;
}

function buildRequest(method: "GET" | "POST", url: string, opts: RequestOptions = {}) {
  const { headers = {}, timeoutMs = 5000, body } = opts;      // defaults in one place
  if (method === "GET" && body !== undefined) throw new Error("GET cannot have a body");
  return Object.freeze({ method, url, headers, timeoutMs, body });
}

