import java.util.ArrayList;
import java.util.List;

interface PriceListener {
    void onPriceChange(int newPrice, int oldPrice);
}

class PriceTicker {
    private final List<PriceListener> listeners = new ArrayList<>();
    private int price = 0;

    Runnable subscribe(PriceListener l) {
        listeners.add(l);
        return () -> listeners.remove(l);             // unsubscribe handle
    }

    void setPrice(int newPrice) {
        if (newPrice == price) return;
        int old = price;
        price = newPrice;
        for (PriceListener l : List.copyOf(listeners)) {   // snapshot: safe if a listener unsubscribes
            l.onPriceChange(newPrice, old);
        }
    }
}

public class Main {
    public static void main(String[] args) {
        PriceTicker ticker = new PriceTicker();
        Runnable unsubChart = ticker.subscribe((p, old) -> System.out.println("chart: redraw at " + p));
        ticker.subscribe((p, old) -> { if (p < old) System.out.println("alert: dropped to " + p); });

        ticker.setPrice(120);
        ticker.setPrice(95);
        unsubChart.run();
        ticker.setPrice(90);
        ticker.setPrice(90);
    }
}

