import java.util.Map;

@FunctionalInterface
interface ShippingStrategy {
    long cost(double weightKg, int distanceKm);
}

class Checkout {
    private ShippingStrategy shipping;              // HAS-A strategy, swappable at runtime

    Checkout(ShippingStrategy shipping) { this.shipping = shipping; }

    void setShipping(ShippingStrategy shipping) { this.shipping = shipping; }

    long total(long itemsTotal, double kg, int km) {
        return itemsTotal + shipping.cost(kg, km);  // delegate: no if/else on the type
    }
}

public class Main {
    // Small strategies can be lambdas; bigger ones become classes (e.g. a Spring @Component each)
    static final Map<String, ShippingStrategy> STRATEGIES = Map.of(
        "standard", (kg, km) -> 60 + Math.round(kg * 10),
        "express", (kg, km) -> 120 + Math.round(kg * 20) + km,
        "pickup", (kg, km) -> 0
    );

    public static void main(String[] args) {
        Checkout checkout = new Checkout(STRATEGIES.get("standard"));
        System.out.println(checkout.total(1000, 2.5, 12));   // 1085 = 1000 + 60 + 25
        checkout.setShipping(STRATEGIES.get("express"));
        System.out.println(checkout.total(1000, 2.5, 12));   // 1182 = 1000 + 120 + 50 + 12
        checkout.setShipping(STRATEGIES.get("pickup"));
        System.out.println(checkout.total(1000, 2.5, 12));   // 1000
    }
}

import java.util.Map;

// TARGET: the interface OUR code is written against
interface SmsSender {
    boolean send(String phone, String text);
}

// ADAPTEE: a third-party / legacy SDK we cannot change (different name, data format, error style)
class LegacySmsGateway {
    int dispatch(Map<String, String> payload) {              // returns an HTTP-like status code
        System.out.println("legacy dispatch " + payload.get("msisdn") + " -> " + payload.get("body"));
        return payload.get("msisdn").startsWith("880") ? 200 : 400;
    }
}

// ADAPTER: implements the target, wraps the adaptee and translates in both directions
class LegacySmsAdapter implements SmsSender {
    private final LegacySmsGateway gateway;

    LegacySmsAdapter(LegacySmsGateway gateway) { this.gateway = gateway; }

    @Override
    public boolean send(String phone, String text) {
        String msisdn = phone.startsWith("0") ? "88" + phone : phone;   // 017... -> 88017...
        int status = gateway.dispatch(Map.of("msisdn", msisdn, "body", text));
        return status == 200;                                           // status code -> boolean
    }
}

public class Main {
    public static void main(String[] args) {
        SmsSender sms = new LegacySmsAdapter(new LegacySmsGateway());   // client sees only SmsSender
        System.out.println(sms.send("01711000000", "Your OTP is 4821"));
    }
}

