  tasks: [{ id: 1, title: "Revise OOP", done: false }],
  all() {
    return this.tasks;
  },
  add(title) {
    if (typeof title !== "string" || !title.trim()) throw new Error("Title is required");
    const task = { id: this.tasks.length + 1, title: title.trim(), done: false };
    this.tasks.push(task);
    return task;
  },
};

