  list: (tasks) =>
    `<ul>${tasks.map((t) => `<li>${t.done ? "[x]" : "[ ]"} ${escapeHtml(t.title)}</li>`).join("")}</ul>`,
};

// CONTROLLER: reads the request, calls the model, picks the view and status code
const TaskController = {
  index(req, res) {
    res.send(TaskView.list(TaskModel.all()));
  },
  create(req, res) {
    try {
      res.status(201).json(TaskModel.add(req.body?.title));
    } catch (e) {
      res.status(400).json({ error: e.message });
    }
  },
};

