import java.util.ArrayList;
import java.util.List;

// MODEL: state + business rules
class TaskModel {
    private final List<String> tasks = new ArrayList<>();

    void add(String title) {
        if (title == null || title.isBlank()) throw new IllegalArgumentException("Title is required");
        tasks.add(title.strip());
    }

    List<String> all() { return List.copyOf(tasks); }
}

// VIEW: presentation only
class TaskView {
    String render(List<String> tasks) {
        StringBuilder sb = new StringBuilder("Tasks:");
        for (int i = 0; i < tasks.size(); i++) sb.append("\n  ").append(i + 1).append(". ").append(tasks.get(i));
        return sb.toString();
    }

    String error(String message) { return "Error: " + message; }
}

// CONTROLLER: handles input, updates the model, chooses the view
class TaskController {
    private final TaskModel model;
    private final TaskView view;

    TaskController(TaskModel model, TaskView view) { this.model = model; this.view = view; }

    String handle(String command, String arg) {
        try {
            if (command.equals("add")) model.add(arg);
            return view.render(model.all());
        } catch (IllegalArgumentException e) {
            return view.error(e.getMessage());
        }
    }
}

public class Main {
    public static void main(String[] args) {
        TaskController controller = new TaskController(new TaskModel(), new TaskView());
        System.out.println(controller.handle("add", "Revise OOP"));
        System.out.println(controller.handle("add", "   "));
        System.out.println(controller.handle("add", "Mock interview"));
    }
}

import java.util.HashMap;
import java.util.Map;
import java.util.Optional;

record User(long id, String email, String name) { }

// The domain-facing contract: looks like a collection of Users, hides SQL / Mongo details
interface UserRepository {
    Optional<User> findById(long id);
    Optional<User> findByEmail(String email);
    User save(User user);
}

// One implementation: in-memory (great for unit tests). Others: JPA, JDBC, MongoDB
class InMemoryUserRepository implements UserRepository {
    private final Map<Long, User> store = new HashMap<>();

    public Optional<User> findById(long id) { return Optional.ofNullable(store.get(id)); }

    public Optional<User> findByEmail(String email) {
        return store.values().stream().filter(u -> u.email().equalsIgnoreCase(email)).findFirst();
    }

    public User save(User user) {
        store.put(user.id(), user);
        return user;
    }
}

// Business logic depends only on the interface
class RegistrationService {
    private final UserRepository users;

    RegistrationService(UserRepository users) { this.users = users; }

    User register(long id, String email, String name) {
        if (users.findByEmail(email).isPresent()) throw new IllegalStateException("Email already registered");
        return users.save(new User(id, email.toLowerCase(), name));
    }
}

public class Main {
    public static void main(String[] args) {
        RegistrationService service = new RegistrationService(new InMemoryUserRepository());
        System.out.println(service.register(1, "Nadia@Mail.com", "Nadia"));
        try {
            service.register(2, "nadia@mail.com", "Someone Else");
        } catch (IllegalStateException e) {
            System.out.println(e.getMessage());
        }
    }
}

interface User { id: number; email: string; name: string }

interface UserRepository {
  findByEmail(email: string): Promise<User | null>;
  save(user: User): Promise<User>;
}

// Tests use this; production uses e.g. a MongoUserRepository built on a Mongoose model:
//   findByEmail: (email) => UserModel.findOne({ email }).lean()
class InMemoryUserRepository implements UserRepository {
  private users = new Map<number, User>();

  async findByEmail(email: string) {
    return [...this.users.values()].find((u) => u.email === email.toLowerCase()) ?? null;
  }

  async save(user: User) {
    this.users.set(user.id, user);
    return user;
  }
}

async function register(repo: UserRepository, user: User): Promise<User> {
  if (await repo.findByEmail(user.email)) throw new Error("Email already registered");
  return repo.save({ ...user, email: user.email.toLowerCase() });
}

const repo = new InMemoryUserRepository();
register(repo, { id: 1, email: "Nadia@Mail.com", name: "Nadia" })
  .then((u) => console.log("saved", u.email))
  .then(() => register(repo, { id: 2, email: "nadia@mail.com", name: "Someone Else" }))
  .catch((e) => console.log(e.message));

import java.time.Duration;
import java.time.Instant;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.atomic.AtomicLong;

enum VehicleType { MOTORBIKE, CAR, TRUCK }
enum SpotSize { SMALL, MEDIUM, LARGE }

record Vehicle(String plate, VehicleType type) { }

class ParkingSpot {
    final String id;
    final SpotSize size;
    private Vehicle parked;                                  // null = free

    ParkingSpot(String id, SpotSize size) { this.id = id; this.size = size; }

    boolean isFree() { return parked == null; }

    boolean fits(Vehicle v) {
        return switch (v.type()) {
            case MOTORBIKE -> true;                          // a bike fits any spot
            case CAR -> size != SpotSize.SMALL;
            case TRUCK -> size == SpotSize.LARGE;
        };
    }

    void park(Vehicle v) { parked = v; }
    void free() { parked = null; }
}

record Ticket(String id, Vehicle vehicle, ParkingSpot spot, Instant entryTime) { }

interface PricingStrategy { long fee(Ticket t, Instant exit); }       // Strategy pattern

class HourlyPricing implements PricingStrategy {
    private static final Map<VehicleType, Long> RATE =
        Map.of(VehicleType.MOTORBIKE, 20L, VehicleType.CAR, 50L, VehicleType.TRUCK, 100L);

    public long fee(Ticket t, Instant exit) {
        long minutes = Duration.between(t.entryTime(), exit).toMinutes();
        long hours = Math.max(1, (minutes + 59) / 60);       // round up, minimum 1 hour
        return hours * RATE.get(t.vehicle().type());
    }
}

class ParkingLot {
    private final List<ParkingSpot> spots;                   // all floors' spots, ordered SMALL -> LARGE (best fit first)
    private final Map<String, Ticket> active = new HashMap<>();
    private final PricingStrategy pricing;
    private final AtomicLong ticketSeq = new AtomicLong();

    ParkingLot(List<ParkingSpot> spots, PricingStrategy pricing) {
        this.spots = spots;
        this.pricing = pricing;
    }

    // synchronized: two entry gates must never be given the same spot
    synchronized Optional<Ticket> park(Vehicle v, Instant now) {
        for (ParkingSpot s : spots) {
            if (s.isFree() && s.fits(v)) {
                s.park(v);
                Ticket t = new Ticket("T" + ticketSeq.incrementAndGet(), v, s, now);
                active.put(t.id(), t);
                return Optional.of(t);
            }
        }
        return Optional.empty();                             // full for this vehicle type
    }

    synchronized long exit(String ticketId, Instant now) {
        Ticket t = active.remove(ticketId);                  // remove = a ticket can't be used twice
        if (t == null) throw new IllegalArgumentException("Unknown or used ticket " + ticketId);
        t.spot().free();
        return pricing.fee(t, now);
    }

    synchronized long freeSpots() { return spots.stream().filter(ParkingSpot::isFree).count(); }
}

public class Main {
    public static void main(String[] args) {
        List<ParkingSpot> spots = List.of(
            new ParkingSpot("F1-S1", SpotSize.SMALL), new ParkingSpot("F1-M1", SpotSize.MEDIUM),
            new ParkingSpot("F1-M2", SpotSize.MEDIUM), new ParkingSpot("F2-L1", SpotSize.LARGE));
        ParkingLot lot = new ParkingLot(spots, new HourlyPricing());
        Instant t0 = Instant.parse("2026-01-10T09:00:00Z");

        Ticket bike = lot.park(new Vehicle("DHA-11", VehicleType.MOTORBIKE), t0).orElseThrow();
        Ticket car = lot.park(new Vehicle("DHA-22", VehicleType.CAR), t0).orElseThrow();
        Ticket truck = lot.park(new Vehicle("CTG-33", VehicleType.TRUCK), t0).orElseThrow();
        System.out.println(bike.spot().id + " " + car.spot().id + " " + truck.spot().id);   // F1-S1 F1-M1 F2-L1
        System.out.println(lot.park(new Vehicle("SYL-44", VehicleType.TRUCK), t0).isPresent()); // false
        System.out.println(lot.exit(car.id(), t0.plus(Duration.ofMinutes(130))));          // 150 (3 h x 50)
        System.out.println(lot.freeSpots());                                               // 2
    }
}

